CREATE TABLE current_engine_source(engine_source_id TEXT PRIMARY KEY,logical_path TEXT NOT NULL UNIQUE CHECK(logical_path LIKE 'lore/editorial/profile-batches/%.json'),source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64 AND source_sha256 NOT GLOB '*[^0-9a-f]*'),source_byte_length INTEGER NOT NULL CHECK(source_byte_length>=0),projection_schema TEXT NOT NULL CHECK(projection_schema='public-character-profile.v1'),projection_sha256 TEXT NOT NULL CHECK(length(projection_sha256)=64 AND projection_sha256 NOT GLOB '*[^0-9a-f]*'),profile_count INTEGER NOT NULL CHECK(profile_count>=0)) STRICT;
CREATE TABLE current_profile(person_id TEXT PRIMARY KEY REFERENCES person(person_id),engine_source_id TEXT NOT NULL REFERENCES current_engine_source(engine_source_id),json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*'),source_ordinal INTEGER NOT NULL CHECK(source_ordinal>=0),UNIQUE(engine_source_id,json_pointer),UNIQUE(engine_source_id,source_ordinal)) STRICT;
CREATE TABLE ability(person_id TEXT NOT NULL REFERENCES current_profile(person_id),ability_ordinal INTEGER NOT NULL CHECK(ability_ordinal BETWEEN 0 AND 7),ability_id TEXT NOT NULL CHECK(ability_id IN ('leadership','strategy','negotiation','management','insight','learning','prowess','endurance')),base_value INTEGER NOT NULL CHECK(base_value BETWEEN 0 AND 20),effective_value INTEGER NOT NULL CHECK(effective_value BETWEEN 0 AND 100),json_pointer TEXT NOT NULL CHECK(json_pointer LIKE '/profiles/%/abilities/%'),PRIMARY KEY(person_id,ability_id),UNIQUE(person_id,ability_ordinal)) STRICT;
CREATE TABLE skill(person_id TEXT NOT NULL REFERENCES current_profile(person_id),skill_ordinal INTEGER NOT NULL CHECK(skill_ordinal>=0),skill_id_presence TEXT NOT NULL CHECK(skill_id_presence IN ('missing','null','value')),skill_id TEXT,name_ko TEXT NOT NULL CHECK(length(trim(name_ko))>0),name_en TEXT NOT NULL CHECK(length(trim(name_en))>0),rating REAL NOT NULL CHECK(rating>=0 AND rating<=99.9 AND abs(rating*10-round(rating*10))<0.00000001),json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/skills/[0-9]*'),PRIMARY KEY(person_id,skill_ordinal),CHECK((skill_id_presence='value' AND skill_id IS NOT NULL) OR (skill_id_presence IN ('missing','null') AND skill_id IS NULL))) STRICT;
CREATE TABLE trait(person_id TEXT NOT NULL REFERENCES current_profile(person_id),trait_ordinal INTEGER NOT NULL CHECK(trait_ordinal>=0),trait_id_presence TEXT NOT NULL CHECK(trait_id_presence IN ('missing','null','value')),trait_id TEXT,name_ko TEXT NOT NULL,name_en TEXT NOT NULL,description_ko TEXT NOT NULL,description_en TEXT NOT NULL,behavior_ko TEXT NOT NULL,behavior_en TEXT NOT NULL,stress_ko TEXT NOT NULL,stress_en TEXT NOT NULL,relationship_ko TEXT NOT NULL,relationship_en TEXT NOT NULL,json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/traits/[0-9]*'),PRIMARY KEY(person_id,trait_ordinal),CHECK((trait_id_presence='value' AND trait_id IS NOT NULL) OR (trait_id_presence IN ('missing','null') AND trait_id IS NULL))) STRICT;
CREATE TABLE effect(person_id TEXT NOT NULL,trait_ordinal INTEGER NOT NULL,effect_ordinal INTEGER NOT NULL CHECK(effect_ordinal>=0),ability_id TEXT NOT NULL CHECK(ability_id IN ('leadership','strategy','negotiation','management','insight','learning','prowess','endurance')),delta INTEGER NOT NULL,json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/traits/[0-9]*/effects/[0-9]*'),PRIMARY KEY(person_id,trait_ordinal,effect_ordinal),FOREIGN KEY(person_id,trait_ordinal) REFERENCES trait(person_id,trait_ordinal)) STRICT;
CREATE TABLE health(person_id TEXT PRIMARY KEY REFERENCES current_profile(person_id),status_presence TEXT NOT NULL CHECK(status_presence IN ('missing','null','value')),status TEXT,json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/health'),CHECK((status_presence='value' AND status IS NOT NULL) OR (status_presence IN ('missing','null') AND status IS NULL))) STRICT;
CREATE TABLE body(person_id TEXT NOT NULL REFERENCES health(person_id),body_ordinal INTEGER NOT NULL CHECK(body_ordinal BETWEEN 0 AND 5),body_part_id TEXT NOT NULL CHECK(body_part_id IN ('left-arm','right-arm','left-leg','right-leg','head','torso')),severity_presence TEXT NOT NULL CHECK(severity_presence IN ('missing','null','value')),severity TEXT,function_presence TEXT NOT NULL CHECK(function_presence IN ('missing','null','value')),function_state TEXT,json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/health/bodyParts/[0-9]*'),PRIMARY KEY(person_id,body_part_id),UNIQUE(person_id,body_ordinal),CHECK((severity_presence='value' AND severity IS NOT NULL) OR (severity_presence IN ('missing','null') AND severity IS NULL)),CHECK((function_presence='value' AND function_state IS NOT NULL) OR (function_presence IN ('missing','null') AND function_state IS NULL))) STRICT;
CREATE TABLE disease(person_id TEXT NOT NULL REFERENCES health(person_id),disease_ordinal INTEGER NOT NULL CHECK(disease_ordinal>=0),disease_id_presence TEXT NOT NULL CHECK(disease_id_presence IN ('missing','null','value')),disease_id TEXT,progression_presence TEXT NOT NULL CHECK(progression_presence IN ('missing','null','value')),progression TEXT,json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/health/diseases/[0-9]*'),PRIMARY KEY(person_id,disease_ordinal),CHECK((disease_id_presence='value' AND disease_id IS NOT NULL) OR (disease_id_presence IN ('missing','null') AND disease_id IS NULL)),CHECK((progression_presence='value' AND progression IS NOT NULL) OR (progression_presence IN ('missing','null') AND progression IS NULL))) STRICT;
CREATE TABLE narrative(person_id TEXT PRIMARY KEY REFERENCES current_profile(person_id),narrative_ko TEXT NOT NULL CHECK(length(trim(narrative_ko))>0),narrative_en TEXT NOT NULL CHECK(length(trim(narrative_en))>0),json_pointer TEXT NOT NULL CHECK(json_pointer GLOB '/profiles/[0-9]*/narrative')) STRICT;
